<section class="page-intro container-wide"><span class="eyebrow">A SPOONFUL OF SOMETHING SPECIAL</span><h1>The pickle pantry.</h1><p>From tangy classics to fiery favourites. Find your kind of flavour.</p></section><section class="container-wide pb-5"><form class="shop-filters" method="get" action="<?= e(rtrim(config('base_url'),'/').'/index.php') ?>"><input type="hidden" name="r" value="shop"><input class="form-control" name="q" value="<?= e($_GET['q']??'') ?>" placeholder="Search your favourite flavour" aria-label="Search products"><select class="form-select" name="category" aria-label="Category"><option value="">All flavours</option><?php foreach($categories as $c): ?><option value="<?= e($c['slug']) ?>" <?= ($_GET['category']??'')===$c['slug']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach ?></select><select class="form-select" name="sort" aria-label="Sort products"><?php foreach([''=>'Our favourites','price'=>'Price: low to high','price-desc'=>'Price: high to low','newest'=>'Newest first'] as $k=>$v): ?><option value="<?= e($k) ?>" <?= ($_GET['sort']??'')===$k?'selected':'' ?>><?= e($v) ?></option><?php endforeach ?></select><button class="btn btn-primary">Find flavours</button></form><div class="category-chips"><a href="<?= e(url('shop')) ?>" class="<?= empty($_GET['category'])?'active':'' ?>">All pickles</a><?php foreach($categories as $c): ?><a class="<?= ($_GET['category']??'')===$c['slug']?'active':'' ?>" href="<?= e(url('shop',['category'=>$c['slug']])) ?>"><?= e($c['name']) ?></a><?php endforeach ?></div><div class="product-grid"><?php foreach($products as $p) require ROOT.'/app/Views/store/card.php'; ?></div><?php if(!$products): ?><div class="empty-state"><h2>No jars found just yet.</h2><p>Try another flavour or browse the full pantry.</p><a class="btn btn-primary" href="<?= e(url('shop')) ?>">Browse all</a></div><?php endif ?><div class="pagination-row"><?php $page=max(1,(int)($_GET['page']??1));if($page>1): ?><a href="<?= e(url('shop',array_merge($_GET,['page'=>$page-1]))) ?>">← Previous</a><?php endif ?><?php if(count($products)===24): ?><a href="<?= e(url('shop',array_merge($_GET,['page'=>$page+1]))) ?>">Next →</a><?php endif ?></div></section>
